patch:
diff --git a/app/Http/Controllers/UnsubscribeController.php b/app/Http/Controllers/UnsubscribeController.php
index 5cd2798..8f86072 100755
--- a/app/Http/Controllers/UnsubscribeController.php
+++ b/app/Http/Controllers/UnsubscribeController.php
@@ -11,11 +11,14 @@ class UnsubscribeController extends Controller
 {
     public function __invoke(Request $request, User $user)
     {
-        $user->update([
-            'marketing_opt_in' => ! $user->marketing_opt_in,
-        ]);
+        $unsubscribed = User::query()
+            ->whereKey($user->getKey())
+            ->where('marketing_opt_in', true)
+            ->update(['marketing_opt_in' => false]);

-        Mail::to($user->email)->send(new UnsubscribeConfirmed);
+        if ($unsubscribed === 1) {
+            Mail::to($user->email)->send(new UnsubscribeConfirmed);
+        }

         return response()->view('unsubscribe-done', ['user' => $user]);
     }
